@startuml

class Customer {
  + name : string
  + address : string
}

class Account {
  + balance : double
}

class SavingsAccount extends Account {
  + interestRate : float
}

class InvestmentAccount extends Account {
}

class Stock {
  + ticker : string
}

class StockOrder {
  + quantity : int
  + price : double
  + commission : double
}

Customer "1" -- "*" Account
Account "0..*" -- "0..*" Stock
StockOrder --> "1" Stock
StockOrder --> "1" InvestmentAccount

@enduml

